#target photoshop
// 只读：把当前文档与图层的信息弹出来看一眼（不修改任何东西）
(function showInfo() {
    if (app.documents.length === 0) {
        alert("请先在 Photoshop 中打开一个文档。");
        return;
    }
    var d = app.activeDocument;
    var l = d.activeLayer;

    var size = "（无边界）";
    try {
        var b = l.bounds;
        size = Math.round(b[2].value - b[0].value) + " × " + Math.round(b[3].value - b[1].value) + " px";
    } catch (e) { }

    var kind = "";
    try { if (l.kind !== undefined && l.kind !== null) kind = " / " + l.kind; } catch (e) { }

    alert("文档：" + d.name
        + "\n尺寸：" + d.width + " × " + d.height
        + "\n分辨率：" + d.resolution + " ppi"
        + "\n\n当前图层：" + l.name
        + "\n类型：" + l.typename + kind
        + "\n图层尺寸：" + size
        + "\n不透明度：" + l.opacity + "%"
        + "\n混合模式：" + l.blendMode);
})();

新建参考线.code:
#target photoshop

(function openGuideLayoutAndAutoLock() {
    // 1. 检查是否有处于打开状态的文档
    if (app.documents.length === 0) {
        alert("请先在 Photoshop 中打开一个文档。");
        return;
    }

    var idNewGuideLayout = stringIDToTypeID("newGuideLayout");
    var SETTINGS_KEY = "AutoSavedGuideLayoutSettings";
    var desc;

    // 2. 读取上次记住的设置（避免恢复成默认 8 栏）
    try {
        desc = app.getCustomOptions(SETTINGS_KEY);
    } catch (e) {
        desc = new ActionDescriptor();
    }

    // 3. 打开“新建参考线版面”弹窗
    try {
        var resultDesc = executeAction(idNewGuideLayout, desc, DialogModes.ALL);

        // 4. 用户点击“确定”后：先记住新参数，随后立即锁定参考线
        if (resultDesc) {
            app.putCustomOptions(SETTINGS_KEY, resultDesc, true);
            lockAllGuides();
        }
    } catch (e) {
        // 用户主动点击“取消”时静默退出
        if (e.number !== 8007) {
            alert("操作失败：" + e.message);
        }
    }

    /**
     * 锁定参考线（等同于勾选菜单栏：视图 -> 锁定参考线）
     */
    function lockAllGuides() {
        try {
            var descSet = new ActionDescriptor();
            var ref = new ActionReference();

            ref.putProperty(charIDToTypeID("Prpr"), stringIDToTypeID("guidesLocked"));
            ref.putEnumerated(charIDToTypeID("capp"), charIDToTypeID("Ordn"), charIDToTypeID("Trgt"));
            descSet.putReference(charIDToTypeID("null"), ref);

            var descPref = new ActionDescriptor();
            // 直接设为 true（锁定状态），即使原本已锁定也不会被意外反转解锁
            descPref.putBoolean(stringIDToTypeID("guidesLocked"), true);
            descSet.putObject(charIDToTypeID("T   "), stringIDToTypeID("guidePreferences"), descPref);

            executeAction(charIDToTypeID("setd"), descSet, DialogModes.NO);
        } catch (err) {
            // 锁定异常时静默忽略，不干扰正常生成的线
        }
    }
})();

测试一下.code:
/*
 * 脚本名称: Add Grain Texture (添加胶片颗粒纹理)
 * 描述: 新建50%灰图层 -> 添加6%杂色 -> 叠加模式 -> 80%不透明度
 * 作者: Photoshop脚本开发专家
 * 兼容性: Photoshop CS6 - CC 2024+
 */

#target photoshop

app.bringToFront();

// 主执行函数
function main() {
    // 1. 检查是否有文档打开
    if (app.documents.length === 0) {
        alert("请先打开一张图片！");
        return;
    }

    var doc = app.activeDocument;

    // 2. 挂起历史记录，方便一步撤销
    doc.suspendHistory("添加颗粒纹理", "processTexture()");
}

// 核心处理逻辑
function processTexture() {
    var doc = app.activeDocument;

    // 保存当前的标尺单位设置，并在结束后恢复，防止单位混乱
    var originalRulerUnits = app.preferences.rulerUnits;
    app.preferences.rulerUnits = Units.PIXELS;

    try {
        // --- 步骤 1: 新建图层 ---
        var layer = doc.artLayers.add();
        layer.name = "胶片颗粒纹理";

        // --- 步骤 2: 填充 50% 灰 (模拟纯色层并栅格化的结果) ---
        // 定义颜色
        var grayColor = new SolidColor();
        if (doc.mode === DocumentMode.CMYK) {
            grayColor.cmyk.cyan = 0;
            grayColor.cmyk.magenta = 0;
            grayColor.cmyk.yellow = 0;
            grayColor.cmyk.black = 50;
        } else {
            // RGB 或其他模式默认为 RGB 128,128,128
            grayColor.rgb.red = 128;
            grayColor.rgb.green = 128;
            grayColor.rgb.blue = 128;
        }

        // 全选并填充
        doc.selection.selectAll();
        doc.selection.fill(grayColor);
        doc.selection.deselect();

        // --- 步骤 3: 添加 6% 杂色 ---
        // applyAddNoise(amount, distribution, monochromatic)
        // amount: 6%
        // distribution: NoiseDistribution.GAUSSIAN (高斯分布质感更好) 或 UNIFORM (平均分布)
        // monochromatic: true (单色，通常用于纹理避免产生彩色噪点)
        layer.applyAddNoise(6, NoiseDistribution.GAUSSIAN, true);

        // --- 步骤 4: 图层模式设为 叠加 (Overlay) ---
        layer.blendMode = BlendMode.OVERLAY;

        // --- 步骤 5: 不透明度设为 80% ---
        layer.opacity = 80;

    } catch (e) {
        // 异常捕获
        alert("脚本执行出错: " + e.message + "\n行号: " + e.line);
    } finally {
        // 恢复标尺设置
        app.preferences.rulerUnits = originalRulerUnits;
    }
}

// 运行脚本
main();
